// SSLErrorInfo constructor
// This function initializes an SSLErrorInfo object with the provided parameters.
void SSLErrorInfo_Init(SSLErrorInfo* error_info, const char* title, const char* details, const char* short_description, const char* extra_info[], size_t extra_info_count) {
    // Initialize title
    strncpy(error_info->title, title, MAX_TITLE_LENGTH - 1);
    error_info->title[MAX_TITLE_LENGTH - 1] = '\0';  // Ensure null-termination

    // Initialize details
    strncpy(error_info->details, details, MAX_DETAILS_LENGTH - 1);
    error_info->details[MAX_DETAILS_LENGTH - 1] = '\0';  // Ensure null-termination

    // Initialize short description
    strncpy(error_info->short_description, short_description, MAX_SHORT_DESCRIPTION_LENGTH - 1);
    error_info->short_description[MAX_SHORT_DESCRIPTION_LENGTH - 1] = '\0';  // Ensure null-termination

    // Initialize extra info
    error_info->extra_info_count = 0;
    for (size_t i = 0; i < extra_info_count && i < MAX_EXTRA_INFO_ITEMS; ++i) {
        size_t len = strlen(extra_info[i]);
        if (len > MAX_EXTRA_INFO_LENGTH - 1) {
            len = MAX_EXTRA_INFO_LENGTH - 1;
        }
        strncpy(error_info->extra_info[error_info->extra_info_count], extra_info[i], len);
        error_info->extra_info[error_info->extra_info_count][len] = '\0';  // Ensure null-termination
        error_info->extra_info_count++;
    }
}

struct SSLErrorInfo {
    char* title;
    char* details;
    char* short_description;
    char** extra_info;
    size_t extra_info_count;
};

