// Construct an SSLErrorInfo object with the provided parameters
void construct_ssl_error_info(SSLErrorInfo* error_info, const char* title, const char* details, const char* short_description, const char** extra_info, size_t extra_info_count) {
    if (!error_info) return;

    strncpy(error_info->title, title, sizeof(error_info->title) - 1);
    error_info->title[sizeof(error_info->title) - 1] = '\0';

    strncpy(error_info->details, details, sizeof(error_info->details) - 1);
    error_info->details[sizeof(error_info->details) - 1] = '\0';

    strncpy(error_info->short_description, short_description, sizeof(error_info->short_description) - 1);
    error_info->short_description[sizeof(error_info->short_description) - 1] = '\0';

    // Initialize extra_info array
    for (size_t i = 0; i < extra_info_count && i < MAX_EXTRA_INFO_ITEMS; i++) {
        strncpy(error_info->extra_info[i], extra_info[i], sizeof(error_info->extra_info[i]) - 1);
        error_info->extra_info[i][sizeof(error_info->extra_info[i]) - 1] = '\0';
    }

    error_info->extra_info_count = (extra_info_count < MAX_EXTRA_INFO_ITEMS) ? extra_info_count : MAX_EXTRA_INFO_ITEMS;
}

struct SSLErrorInfo {
