    char* details;
    char* short_description;
    char** extra_info;
    int extra_info_count;
};

void construct_SSLErrorInfo(
    struct SSLErrorInfo* error_info,
    const char* title,
    const char* details,
    const char* short_description,
    const char** extra_info,
    int extra_info_count) {
    error_info->title = strdup(title);
    error_info->details = strdup(details);
    error_info->short_description = strdup(short_description);
    error_info->extra_info_count = extra_info_count;
    error_info->extra_info = (char**)malloc(extra_info_count * sizeof(char*));
    for (int i = 0; i < extra_info_count; i++) {
        error_info->extra_info[i] = strdup(extra_info[i]);
    }
}

#include <string.h>

// Assuming string16 is a defined type, typically as a wchar_t[16] or similar
typedef wchar_t string16[16];

// Assuming SSLErrorInfo is a defined struct
typedef struct {
    string16 title;
    string16 details;
    string16 short_description;
    string16 extra_info[/* size based on expected max items */];
    size_t extra_info_count;
} SSLErrorInfo;

void SSLErrorInfo_Init(SSLErrorInfo* error_info, string16 title, string16 details, string16 short_description, string16* extra_info, size_t extra_info_count) {
    if (error_info == NULL) {
        return;
    }

    wcsncpy(error_info->title, title, sizeof(string16));
    wcsncpy(error_info->details, details, sizeof(string16));
    wcsncpy(error_info->short_description, short_description, sizeof(string16));
    error_info->extra_info_count = 0;

    if (extra_info != NULL && extra_info_count > 0) {
        size_t count = extra_info_count;
        for (size_t i = 0; i < count; ++i) {
            wcsncpy(error_info->extra_info[i], extra_info[i], sizeof(string16));
            ++error_info->extra_info_count;
        }
    }
}
